#!/bin/bash
# ============================================================
# TSNsched 开发环境 + TSN Studio Web GUI 一键部署脚本
# 适用: Ubuntu/Debian（apt 系）；执行: bash deploy-tsn.sh [仓库路径]
# ============================================================
set -e
REPO_DIR="${1:-$HOME/TSNsched}"
APP="$HOME/tsn-studio"
PORT=8137

echo "========== [1/6] 安装依赖 =========="
sudo apt-get update -qq
sudo apt-get install -y -qq openjdk-17-jdk libz3-java python3 git > /dev/null
echo "Java: $(java -version 2>&1 | head -1)"
ls /usr/share/java/com.microsoft.z3.jar > /dev/null && echo "Z3 Java 绑定: OK"

echo "========== [2/6] 定位 TSNsched 仓库 =========="
if [ ! -f "$REPO_DIR/Script/libs/TSNsched.jar" ]; then
  echo "未在 $REPO_DIR 找到仓库，尝试 git clone ..."
  git clone --depth 1 https://github.com/ACassimiro/TSNsched "$REPO_DIR" || {
    echo "!! clone 失败，请手动将 TSNsched 仓库放到 $REPO_DIR 后重跑: bash $0 <路径>"; exit 1; }
fi
echo "仓库: $REPO_DIR"

echo "========== [3/6] 部署 Web GUI =========="
mkdir -p "$APP/web" "$APP/backend"
base64 -d > "$APP/web/index.html" << 'GUI_B64_EOF'

GUI_B64_EOF
echo "GUI: $APP/web/index.html ($(du -h $APP/web/index.html | cut -f1))"

echo "========== [4/6] 写入后端入口与演示拓扑 =========="
cat > "$APP/backend/RunDemo.java" << 'JAVA_EOF'
import com.tsnsched.core.interface_manager.JSONParser;
import com.tsnsched.core.network.*;
import com.tsnsched.core.schedule_generator.*;

public class RunDemo {
    public static void main(String[] args) throws Exception {
        String input = args.length > 0 ? args[0] : "demo.json";
        JSONParser parser = new JSONParser(input);
        Network net = parser.parseInput();
        ScheduleGenerator gen = new ScheduleGenerator();
        gen.setEnableConsoleOutput(true);
        gen.generateSchedule(net);
        parser.generateOutput(net);
        System.out.println("[OK] 求解完成，结果已写入 output.json");
    }
}

JAVA_EOF
cat > "$APP/backend/demo.json" << 'JSON_EOF'
{
 "switches": [
  {
   "name": "SW1",
   "scheduleType": "hypercycle",
   "defaultTimeToTravel": 1,
   "defaultPortSpeed": 125,
   "defaultGuardBandSize": 10,
   "ports": [
    {
     "name": "eth0",
     "connectsTo": "PLC1",
     "timeToTravel": 1,
     "portSpeed": 125,
     "guardBandSize": 10,
     "scheduleType": "microcycle",
     "maximumSlotDuration": 500,
     "cycleStart": 0
    },
    {
     "name": "eth1",
     "connectsTo": "CAM1",
     "timeToTravel": 1,
     "portSpeed": 125,
     "guardBandSize": 10,
     "scheduleType": "microcycle",
     "maximumSlotDuration": 500,
     "cycleStart": 0
    },
    {
     "name": "eth2",
     "connectsTo": "CTRL1",
     "timeToTravel": 1,
     "portSpeed": 125,
     "guardBandSize": 10,
     "scheduleType": "microcycle",
     "maximumSlotDuration": 500,
     "cycleStart": 0
    },
    {
     "name": "eth3",
     "connectsTo": "SW2",
     "timeToTravel": 1,
     "portSpeed": 125,
     "guardBandSize": 10,
     "scheduleType": "microcycle",
     "maximumSlotDuration": 500,
     "cycleStart": 0
    },
    {
     "name": "eth4",
     "connectsTo": "SENSOR1",
     "timeToTravel": 1,
     "portSpeed": 125,
     "guardBandSize": 10,
     "scheduleType": "microcycle",
     "maximumSlotDuration": 500,
     "cycleStart": 0
    }
   ]
  },
  {
   "name": "SW2",
   "scheduleType": "hypercycle",
   "defaultTimeToTravel": 1,
   "defaultPortSpeed": 125,
   "defaultGuardBandSize": 10,
   "ports": [
    {
     "name": "eth0",
     "connectsTo": "SW1",
     "timeToTravel": 1,
     "portSpeed": 125,
     "guardBandSize": 10,
     "scheduleType": "microcycle",
     "maximumSlotDuration": 500,
     "cycleStart": 0
    },
    {
     "name": "eth1",
     "connectsTo": "HMI1",
     "timeToTravel": 1,
     "portSpeed": 125,
     "guardBandSize": 10,
     "scheduleType": "microcycle",
     "maximumSlotDuration": 500,
     "cycleStart": 0
    }
   ]
  }
 ],
 "devices": [
  {
   "name": "PLC1",
   "defaultFirstSendingTime": 0,
   "defaultPacketPeriodicity": 500,
   "defaultHardConstraintTime": 300,
   "defaultPacketSize": 1500
  },
  {
   "name": "CAM1",
   "defaultFirstSendingTime": 0,
   "defaultPacketPeriodicity": 1000,
   "defaultHardConstraintTime": 800,
   "defaultPacketSize": 3000
  },
  {
   "name": "CTRL1",
   "defaultFirstSendingTime": 0,
   "defaultPacketPeriodicity": 1000,
   "defaultHardConstraintTime": 1000,
   "defaultPacketSize": 1500
  },
  {
   "name": "HMI1",
