   "defaultPacketPeriodicity": 1000,
   "defaultHardConstraintTime": 1000,
   "defaultPacketSize": 1500
  },
  {
   "name": "SENSOR1",
   "defaultFirstSendingTime": 0,
   "defaultPacketPeriodicity": 1000,
   "defaultHardConstraintTime": 1000,
   "defaultPacketSize": 1500
  }
 ],
 "flows": [
  {
   "name": "control",
   "type": "unicast",
   "sourceDevice": "PLC1",
   "endDevices": [
    "CTRL1"
   ],
   "hops": [
    {
     "currentNodeName": "PLC1",
     "nextNodeName": "SW1"
    },
    {
     "currentNodeName": "SW1",
     "nextNodeName": "CTRL1"
    }
   ]
  },
  {
   "name": "video",
   "type": "unicast",
   "sourceDevice": "CAM1",
   "endDevices": [
    "HMI1"
   ],
   "hops": [
    {
     "currentNodeName": "CAM1",
     "nextNodeName": "SW1"
    },
    {
     "currentNodeName": "SW1",
     "nextNodeName": "SW2"
    },
    {
     "currentNodeName": "SW2",
     "nextNodeName": "HMI1"
    }
   ]
  },
  {
   "name": "telemetry",
   "type": "unicast",
   "sourceDevice": "SENSOR1",
   "endDevices": [
    "HMI1"
   ],
   "hops": [
    {
     "currentNodeName": "SENSOR1",
     "nextNodeName": "SW1"
    },
    {
     "currentNodeName": "SW1",
     "nextNodeName": "SW2"
    },
    {
     "currentNodeName": "SW2",
     "nextNodeName": "HMI1"
    }
   ]
  }
 ]
}
JSON_EOF

echo "========== [5/6] 编译并用 Z3 后端求解演示拓扑 =========="
cd "$APP/backend"
LIBS="$REPO_DIR/Script/libs"
javac -d . -classpath "/usr/share/java/com.microsoft.z3.jar:$LIBS/gson-2.8.6.jar:$LIBS/java-json.jar:$LIBS/TSNsched.jar" RunDemo.java
java -Djava.library.path=/usr/lib/x86_64-linux-gnu/jni \
     -classpath ".:/usr/share/java/com.microsoft.z3.jar:$LIBS/gson-2.8.6.jar:$LIBS/java-json.jar:$LIBS/TSNsched.jar" \
     RunDemo demo.json 2>&1 | grep -Ev "^WARNING|log4j" | tail -8
echo "--- 求解结果(output.json 摘要) ---"
python3 -c "import json;d=json.load(open('output.json'));[print(f\"  流 {f['name']}: 平均延迟 {f['averageLatency']:.2f}us, 抖动 {f['jitter']}\") for f in d['flows']]"

echo "========== [6/6] 启动 Web GUI 服务 =========="
pkill -f "http.server $PORT" 2>/dev/null || true
cd "$APP/web" && nohup python3 -m http.server $PORT > "$APP/gui.log" 2>&1 &
sleep 1
IP=$(hostname -I | awk '{print $1}')
echo ""
echo "============================================================"
echo "  部署完成!"
echo "  Web GUI:   http://$IP:$PORT/   (Win11 浏览器直接访问)"
echo "  后端目录:  $APP/backend (output.json 为求解结果)"
echo "  停止 GUI:  pkill -f \"http.server $PORT\""
echo "============================================================"
